   528→              sessionStorage.removeItem('zcc:valid');
   529→              sessionStorage.removeItem('zcc:zip');
   530→              window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
   531→            } catch(e) {}
   532→            return;
   533→          }
