   537→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
   538→            sessionStorage.setItem('zcc:zip', zip);
   539→            sessionStorage.setItem('zcc:shop', SHOP);
   540→            // Fire custom event for other scripts to listen to
